// A small standard-library Go syntax reader used by the dependency scanner.
// It describes declarations and unbound references; all graph and module
// resolution logic lives in the application.
package main

import (
    "bufio"
    "encoding/json"
    "go/ast"
    "go/parser"
    "go/token"
    "os"
    "sort"
    "strconv"
)

type Import struct { Path string `json:"path"`; Alias string `json:"alias"` }
type Reference struct { Name string `json:"name"`; Member string `json:"member,omitempty"`; Offset int `json:"offset"` }
type Description struct {
    Package string `json:"package"`
    Imports []Import `json:"imports"`
    Declarations []string `json:"declarations"`
    References []Reference `json:"references"`
    Error string `json:"error,omitempty"`
}

func describe(path string) Description {
    d := Description{Imports: []Import{}, Declarations: []string{}, References: []Reference{}}
    set := token.NewFileSet()
    f, err := parser.ParseFile(set, path, nil, 0)
    if err != nil { d.Error = err.Error(); return d }
    d.Package = f.Name.Name
    for _, i := range f.Imports {
        p, err := strconv.Unquote(i.Path.Value)
        if err != nil { continue }
        alias := ""
        if i.Name != nil { alias = i.Name.Name }
        d.Imports = append(d.Imports, Import{p, alias})
    }
    for n := range f.Scope.Objects { d.Declarations = append(d.Declarations, n) }
    sort.Strings(d.Declarations)
    member := map[*ast.Ident]string{}
    ast.Inspect(f, func(n ast.Node) bool {
        if s, ok := n.(*ast.SelectorExpr); ok {
            if id, ok := s.X.(*ast.Ident); ok { member[id] = s.Sel.Name }
        }
        return true
    })
    for _, id := range f.Unresolved {
        d.References = append(d.References, Reference{id.Name, member[id], int(id.Pos())})
    }
    sort.SliceStable(d.References, func(i,j int) bool { return d.References[i].Offset < d.References[j].Offset })
    return d
}

func main() {
    in := bufio.NewScanner(os.Stdin)
    in.Buffer(make([]byte, 4096), 4*1024*1024)
    out := json.NewEncoder(os.Stdout)
    for in.Scan() {
        var path string
        if err := json.Unmarshal(in.Bytes(), &path); err != nil { _ = out.Encode(Description{Error: err.Error()}); continue }
        _ = out.Encode(describe(path))
    }
}
