"""Small shared types and filesystem operations."""
import errno
import os

class Failure(Exception):
    def __init__(self, message, code=1):
        super().__init__(message)
        self.code = code

def absolute(path, base=None):
    return os.path.normpath(os.path.join(base or os.getcwd(), path))

def io_message(exc, operation='open', path=None):
    name = path if path is not None else exc.filename
    reasons = {
        errno.ENOENT: 'no such file or directory',
        errno.EACCES: 'permission denied',
        errno.EPERM: 'operation not permitted',
        errno.EISDIR: 'is a directory',
        errno.ENOTDIR: 'not a directory',
        errno.ELOOP: 'too many levels of symbolic links',
    }
    return '%s %s: %s' % (operation, name, reasons.get(exc.errno, (exc.strerror or str(exc)).lower()))

def read_text(path):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            return f.read()
    except OSError as e:
        raise Failure(io_message(e, 'read' if e.errno == errno.EISDIR else 'open', path))

def parents(path):
    p = os.path.dirname(path) if not os.path.isdir(path) else path
    while True:
        yield p
        q = os.path.dirname(p)
        if q == p:
            return
        p = q

def unique(values):
    return list(dict.fromkeys(values))
