"""Path globbing with recursive stars, character ranges, and brace choices."""
import os
import re
from functools import lru_cache
from common import Failure, absolute

class BadPattern(ValueError):
    pass

def choices(pattern):
    # Brace choices may themselves contain choices and escaped metacharacters.
    start = None
    depth = 0
    bracket = False
    escape = False
    for i, c in enumerate(pattern):
        if escape:
            escape = False
            continue
        if c == '\\':
            escape = True
            continue
        if c == '[':
            bracket = True
        elif c == ']':
            bracket = False
        if bracket:
            continue
        if c == '{':
            if depth == 0:
                start = i
            depth += 1
        elif c == '}':
            if depth == 0:
                raise BadPattern()
            depth -= 1
            if depth == 0:
                inner = pattern[start+1:i]
                parts, j, d = [], 0, 0
                for k, ch in enumerate(inner):
                    if ch == '{': d += 1
                    elif ch == '}': d -= 1
                    elif ch == ',' and d == 0:
                        parts.append(inner[j:k]); j = k + 1
                parts.append(inner[j:])
                result = []
                for part in parts:
                    result.extend(choices(pattern[:start] + part + pattern[i+1:]))
                return result
    if depth:
        raise BadPattern()
    return [pattern]

def one_regex(pattern):
    pieces = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '\\':
            i += 1
            if i >= len(pattern): raise BadPattern()
            pieces.append(re.escape(pattern[i]))
        elif c == '*':
            j = i
            while j < len(pattern) and pattern[j] == '*': j += 1
            n = j - i
            if n >= 2 and (i == 0 or pattern[i-1] == '/') and (j == len(pattern) or pattern[j] == '/'):
                if j < len(pattern):
                    pieces.append('(?:.*/)?'); j += 1
                else:
                    pieces.append('.*')
            else:
                pieces.append('[^/]*')
            i = j
            continue
        elif c == '?':
            pieces.append('[^/]')
        elif c == '[':
            j = i + 1
            negate = False
            if j < len(pattern) and pattern[j] in ('!', '^'):
                negate = True; j += 1
            k = j
            if j < len(pattern) and pattern[j] == ']':
                j += 1
            while j < len(pattern) and pattern[j] != ']':
                if pattern[j] == '\\': j += 1
                j += 1
            if j >= len(pattern) or j == k:
                raise BadPattern()
            s = pattern[k:j]
            if '/' in s:
                raise BadPattern()
            pieces.append('[' + ('^' if negate else '') + s + ']')
            i = j
        elif c in '{}':
            raise BadPattern()
        else:
            pieces.append(re.escape(c))
        i += 1
    try:
        return re.compile('^' + ''.join(pieces) + '$')
    except re.error:
        raise BadPattern()

@lru_cache(maxsize=2048)
def compile_pattern(pattern):
    return tuple(one_regex(p) for p in choices(pattern))

def matches(pattern, path):
    return any(r.fullmatch(path) for r in compile_pattern(pattern))

def glob_paths(pattern, base=None):
    """Return sorted matches, including directory matches, without shell expansion."""
    patt = absolute(pattern, base)
    compile_pattern(patt)
    results = set()
    for option in choices(patt):
        components = option.split('/')
        prefix = []
        for part in components:
            if any(ch in part for ch in '*?[\\'):
                break
            prefix.append(part)
        anchor = '/'.join(prefix) or '/'
        if len(prefix) == len(components):
            if os.path.lexists(anchor): results.add(os.path.normpath(anchor))
            continue
        if not os.path.isdir(anchor):
            continue
        regex = one_regex(option)
        if regex.fullmatch(anchor): results.add(anchor)
        # Stop at the maximum number of path components when there is no **.
        remainder = components[len(prefix):]
        deep = '**' in remainder
        maxdepth = len(remainder)
        seen_dirs = set()
        for root, dirs, files in os.walk(anchor, followlinks=True):
            try:
                stat = os.stat(root)
                key = (stat.st_dev, stat.st_ino)
                if key in seen_dirs:
                    dirs[:] = []
                    continue
                seen_dirs.add(key)
            except OSError:
                dirs[:] = []
                continue
            dirs.sort(); files.sort()
            relative = os.path.relpath(root, anchor)
            depth = 0 if relative == '.' else relative.count('/') + 1
            for name in dirs + files:
                path = os.path.join(root, name)
                if regex.fullmatch(path): results.add(path)
            if not deep and depth + 1 >= maxdepth:
                dirs[:] = []
    return sorted(results)

class Selection:
    def __init__(self, only=(), exclude=()):
        self.only = list(only)
        self.exclude = list(exclude)
        for name, patterns in [('exclude', self.exclude), ('only', self.only)]:
            for p in patterns:
                try: compile_pattern(p)
                except BadPattern:
                    raise Failure("%s pattern '%s' is not correctly formatted" % (name, p))

    def accepts(self, path, ignore_only=False):
        if any(matches(p, path) for p in self.exclude): return False
        return ignore_only or not self.only or any(matches(p, path) for p in self.only)
EOF"}

