            raise BadPattern()
        else:
            pieces.append(re.escape(c))
        i += 1
    try:
        return re.compile('^' + ''.join(pieces) + '$')
    except re.error:
        raise BadPattern()

@lru_cache(maxsize=2048)
def compile_pattern(pattern):
    return tuple(one_regex(p) for p in choices(pattern))

def matches(pattern, path):
    return any(r.fullmatch(path) for r in compile_pattern(pattern))

def glob_paths(pattern, base=None):
    """Return sorted matches, including directory matches, without shell expansion."""
    patt = absolute(pattern, base)
    compile_pattern(patt)
    results = set()
    for option in choices(patt):
        components = option.split('/')
        prefix = []
        for part in components:
            if any(ch in part for ch in '*?[\\'):
                break
            prefix.append(part)
        anchor = '/'.join(prefix) or '/'
        if len(prefix) == len(components):
            if os.path.lexists(anchor): results.add(os.path.normpath(anchor))
            continue
        if not os.path.isdir(anchor):
            continue
        regex = one_regex(option)
        if regex.fullmatch(anchor): results.add(anchor)
        # Stop at the maximum number of path components when there is no **.
        remainder = components[len(prefix):]
        deep = '**' in remainder
        maxdepth = len(remainder)
        seen_dirs = set()
        for root, dirs, files in os.walk(anchor, followlinks=True):
            try:
                stat = os.stat(root)
                key = (stat.st_dev, stat.st_ino)
                if key in seen_dirs:
                    dirs[:] = []
                    continue
                seen_dirs.add(key)
            except OSError:
                dirs[:] = []
                continue
            dirs.sort(); files.sort()
            relative = os.path.relpath(root, anchor)
            depth = 0 if relative == '.' else relative.count('/') + 1
            for name in dirs + files:
                path = os.path.join(root, name)
                if regex.fullmatch(path): results.add(path)
            if not deep and depth + 1 >= maxdepth:
                dirs[:] = []
    return sorted(results)

class Selection:
    def __init__(self, only=(), exclude=()):
        self.only = list(only)
        self.exclude = list(exclude)
        for name, patterns in [('exclude', self.exclude), ('only', self.only)]:
            for p in patterns:
                try: compile_pattern(p)
                except BadPattern:
                    raise Failure("%s pattern '%s' is not correctly formatted" % (name, p))

    def accepts(self, path, ignore_only=False):
        if any(matches(p, path) for p in self.exclude): return False
        return ignore_only or not self.only or any(matches(p, path) for p in self.only)
