    depth = 0
    quote = None
    escape = False
    for i, c in enumerate(text):
        if quote:
            if escape: escape = False
            elif c == '\\' and quote == '"': escape = True
            elif c == quote: quote = None
            continue
        if c in "\"'": quote = c
        elif c in '[{(': depth += 1
        elif c in ']})': depth -= 1
        elif c == delimiter and depth == 0:
            result.append(text[start:i].strip()); start = i + 1
    result.append(text[start:].strip())
    return result

def colon_at(text, flow=False):
    depth = 0
    quote = None
    escape = False
    for i, c in enumerate(text):
        if quote:
            if escape: escape = False
            elif c == '\\' and quote == '"': escape = True
            elif c == quote: quote = None
            continue
        if c in "\"'": quote = c
        elif c in '[{(': depth += 1
        elif c in ']})': depth -= 1
        elif c == ':' and depth == 0 and (flow or i+1 == len(text) or text[i+1].isspace()): return i
    return -1

class YamlReader:
    def __init__(self, text):
        self.original = text.lstrip('\ufeff').splitlines()
        self.lines = []
        self.anchors = {}
        self.duplicates = []
        found = False
        for number, raw in enumerate(self.original, 1):
            if '\t' in raw[:len(raw)-len(raw.lstrip())]:
                raise YamlError('yaml: line %d: found character that cannot start any token' % number)
            body = strip_comment(raw.lstrip(' '))
            if not body:
                continue
            if body == '---':
                if found: break
                continue
            if body == '...': break
            if body.startswith('%YAML'): continue
            found = True
            self.lines.append((len(raw)-len(raw.lstrip(' ')), body, number))
        self.i = 0

    def scalar(self, text, line):
        text = text.strip()
        if text.startswith('&'):
            m = re.match(r'&([^\s]+)\s*(.*)', text, re.S)
            name, rest = m.groups()
            node = self.scalar(rest, line)
            self.anchors[name] = node
            return node
        if text.startswith('*') and not any(c.isspace() for c in text):
            name = text[1:]
            if name not in self.anchors:
                raise YamlError("yaml: unknown anchor '%s' referenced" % name)
            node = copy.deepcopy(self.anchors[name]); node.line = line
            return node
        if text.startswith('!!str '):
            n = self.scalar(text[6:], line)
            return Node(str(n.value or ''), line, text)
        if text.startswith('!!bool '):
            return Node(text[7:].lower() == 'true', line, text)
        if text.startswith('['):
            if not text.endswith(']'):
                raise YamlError('yaml: line %d: did not find expected node content' % line)
            inner = text[1:-1].strip()
            values = [] if not inner else [self.scalar(x, line) for x in top_split(inner) if x != '']
            return Node(values, line, text)
        if text.startswith('{'):
            if not text.endswith('}'):
                raise YamlError("yaml: line %d: did not find expected ',' or '}'" % line)
            result = {}
            for item in top_split(text[1:-1]):
                if not item: continue
                pos = colon_at(item, True)
                if pos < 0:
                    key, val = item, ''
                else:
                    key, val = item[:pos], item[pos+1:]
                kn = self.scalar(key, line)
                k = str(kn.value) if kn.value is not None else ''
                self.add(result, k, self.scalar(val, line))
            return Node(result, line, text)
        if text.startswith("'"):
            if len(text) < 2 or not text.endswith("'"):
                raise YamlError('yaml: line %d: found unexpected end of stream' % line)
            return Node(text[1:-1].replace("''", "'"), line, text)
        if text.startswith('"'):
            try:
                val = json.loads(text)
            except (ValueError, TypeError):
                try: val = ast.literal_eval(text)
                except Exception:
                    raise YamlError('yaml: line %d: found unexpected end of stream' % line)
            return Node(val, line, text)
        if text in ('', '~', 'null', 'Null', 'NULL'):
            return Node(None, line, text)
        if text in ('true', 'True', 'TRUE'): return Node(True, line, text)
        if text in ('false', 'False', 'FALSE'): return Node(False, line, text)
        if re.fullmatch(r'[-+]?\d+', text):
            try: return Node(int(text), line, text)
            except ValueError: pass
        if re.fullmatch(r'[-+]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][-+]?\d+)?', text):
            try: return Node(float(text), line, text)
            except ValueError: pass
        if text[0:1] in ('@', '`'):
            raise YamlError('yaml: line %d: found character that cannot start any token' % line)
        if colon_at(text) >= 0:
            raise YamlError('yaml: line %d: mapping values are not allowed in this context' % line)
        return Node(text, line, text)

    def add(self, mapping, key, value):
        if key in mapping:
            self.duplicates.append('  line %d: mapping key "%s" already defined at line %d' % (value.line, key, mapping[key].line))
        mapping[key] = value

    def block_scalar(self, indicator, indent, line):
        # Read the original lines to retain embedded blank lines in literal text.
        start = line
        end = start
        content_indent = None
        while end < len(self.original):
            raw = self.original[end]
            if raw.strip():
                n = len(raw)-len(raw.lstrip(' '))
                if n <= indent: break
                if content_indent is None: content_indent = n
            end += 1
        content_indent = content_indent if content_indent is not None else indent + 1
        lines = [s[content_indent:] if len(s) >= content_indent else '' for s in self.original[start:end]]
        if indicator.startswith('>'):
            value = ''
            for j, text in enumerate(lines):
                value += text
                if j+1 < len(lines): value += '\n' if not text or not lines[j+1] else ' '
            value += '\n'
        else:
            value = '\n'.join(lines) + ('\n' if lines else '')
        if '-' in indicator: value = value.rstrip('\n')
        elif '+' not in indicator: value = value.rstrip('\n') + ('\n' if value else '')
