            m = re.match(r'&([^\s]+)\s*(.*)', text, re.S)
            anchor, text = m.groups()
        if text.startswith(('|', '>')):
            node = self.block_scalar(text, indent, line)
        elif text:
            # A flow value may span physical lines.
            if text.startswith(('[', '{')):
                while self.i < len(self.lines) and not self.flow_closed(text):
                    text += ' ' + self.lines[self.i][1]
                    self.i += 1
            node = self.scalar(text, line)
        elif self.i < len(self.lines) and (self.lines[self.i][0] > indent or (self.lines[self.i][0] == indent and self.lines[self.i][1].startswith('-'))):
            node = self.block(self.lines[self.i][0])
        else:
            node = Node(None, line)
        if anchor: self.anchors[anchor] = copy.deepcopy(node)
        return node

    @staticmethod
    def flow_closed(text):
        depth = 0
        quote = None
        escape = False
        for c in text:
            if quote:
                if escape: escape = False
                elif c == '\\' and quote == '"': escape = True
                elif c == quote: quote = None
            elif c in "\"'": quote = c
            elif c in '[{': depth += 1
            elif c in ']}': depth -= 1
        return depth == 0 and quote is None

    def map_item(self, mapping, text, indent, line):
        pos = colon_at(text)
        if pos < 0:
            raise YamlError('yaml: line %d: could not find expected ":"' % line)
        keytext = text[:pos].strip()
        keynode = self.scalar(keytext, line)
        if isinstance(keynode.value, (dict, list)):
            raise YamlError('yaml: invalid map key')
        key = str(keynode.value) if keynode.value is not None else ''
        node = self.value_after(text[pos+1:], indent, line)
        if key == '<<':
            if isinstance(node.value, dict):
                for k, v in node.value.items():
                    if k not in mapping: mapping[k] = copy.deepcopy(v)
            elif isinstance(node.value, list):
                for n in node.value:
                    if isinstance(n.value, dict):
                        for k,v in n.value.items():
                            if k not in mapping: mapping[k] = copy.deepcopy(v)
        else:
            self.add(mapping, key, node)

    def block(self, indent):
        firstline = self.lines[self.i][2]
        islist = self.lines[self.i][1] == '-' or self.lines[self.i][1].startswith('- ')
        if islist:
            result = []
            while self.i < len(self.lines):
                n, text, line = self.lines[self.i]
                if n != indent or not (text == '-' or text.startswith('- ')): break
                self.i += 1
                remainder = text[1:].lstrip()
                if colon_at(remainder) >= 0 and not remainder.startswith(('[', '{')):
                    m = {}
                    itemindent = indent + 2
                    self.map_item(m, remainder, itemindent, line)
                    while self.i < len(self.lines) and self.lines[self.i][0] > indent:
                        nn, tt, ll = self.lines[self.i]
                        self.i += 1
                        self.map_item(m, tt, nn, ll)
                    result.append(Node(m, line))
                else:
                    result.append(self.value_after(remainder, indent, line))
            return Node(result, firstline)
        # A single scalar/flow document is also legal YAML.
        if colon_at(self.lines[self.i][1]) < 0 or self.lines[self.i][1].startswith(('[', '{')):
            _, text, line = self.lines[self.i]
            self.i += 1
            return self.value_after(text, indent, line)
        result = {}
        while self.i < len(self.lines):
            n, text, line = self.lines[self.i]
            if n < indent: break
            if n != indent or text.startswith('- '):
                raise YamlError('yaml: line %d: did not find expected key' % line)
            self.i += 1
            self.map_item(result, text, indent, line)
        return Node(result, firstline)

    def parse(self):
        if not self.lines: raise YamlError('EOF')
        node = self.block(self.lines[0][0])
        if self.i < len(self.lines):
            raise YamlError('yaml: line %d: did not find expected key' % self.lines[self.i][2])
        if self.duplicates:
            raise YamlError('yaml: unmarshal errors:\n' + '\n'.join(self.duplicates))
        return node


def plain(node):
    if isinstance(node.value, dict): return {k: plain(v) for k,v in node.value.items()}
    if isinstance(node.value, list): return [plain(v) for v in node.value]
    return node.value

ALLOW_TYPE = 'struct { To []string "yaml:\\"to\\""; Reason string "yaml:\\"reason\\"" }'
DENY_TYPE = 'struct { To string "yaml:\\"to\\""; Reason string "yaml:\\"reason\\"" }'

class Validator:
    def __init__(self): self.errors = []

    def mismatch(self, node, target):
        value = node.value
        if isinstance(value, list): desc = '!!seq'
        elif isinstance(value, dict): desc = '!!map'
        elif isinstance(value, bool): desc = '!!bool `%s`' % str(value).lower()
        elif isinstance(value, int): desc = '!!int `%s`' % value
        elif isinstance(value, float): desc = '!!float `%s`' % value
        else:
            s = str(value)
            if len(s) > 10: s = s[:7] + '...'
            desc = '!!str `%s`' % s
        self.errors.append('  line %d: cannot unmarshal %s into %s' % (node.line, desc, target))

    def string(self, node):
        v = node.value
        if v is None: return ''
        if isinstance(v, (dict,list)):
            self.mismatch(node, 'string'); return ''
        return str(v).lower() if isinstance(v, bool) else str(v)

    def boolean(self, node):
        if node.value is None: return False
        if isinstance(node.value, bool): return node.value
        if isinstance(node.value, str):
            if node.value.lower() in ('yes', 'on', 'true'): return True
            if node.value.lower() in ('no', 'off', 'false'): return False
        self.mismatch(node, 'bool'); return False

    def strings(self, node):
        if node.value is None: return []
        if not isinstance(node.value, list):
            self.mismatch(node, '[]string'); return []
        return [self.string(v) for v in node.value]

    def object(self, node, typename, handlers):
        if node.value is None: return {}
        if not isinstance(node.value, dict):
            self.mismatch(node, typename); return {}
        result = {}
        for k, v in node.value.items():
            if k not in handlers:
                self.errors.append('  line %d: field %s not found in type %s' % (v.line, k, typename))
            else:
                result[k] = handlers[k](v)
        return result

    def allowentry(self, node):
        if isinstance(node.value, list): return {'to': self.strings(node), 'reason': ''}
        obj = self.object(node, ALLOW_TYPE, {'to': self.strings, 'reason': self.string})
        return {'to': obj.get('to', []), 'reason': obj.get('reason', '')}

    def denyentry(self, node):
        if node.value is None: return []
        if not isinstance(node.value, list):
            self.mismatch(node, '[]check.BlackListEntry'); return []
        result = []
        for n in node.value:
            if not isinstance(n.value, (dict,list)):
                result.append({'to':self.string(n), 'reason':''})
            else:
                o = self.object(n, DENY_TYPE, {'to':self.string, 'reason':self.string})
                result.append({'to':o.get('to',''), 'reason':o.get('reason','')})
        return result

    def mapping(self, node, target, action):
        if node.value is None: return {}
        if not isinstance(node.value, dict):
            self.mismatch(node, target); return {}
        return {k:action(v) for k,v in node.value.items()}

    def check(self, node):
        return self.object(node, 'check.Config', {
            'entrypoints': self.strings,
            'allowCircularDependencies': self.boolean,
            'allow': lambda n: self.mapping(n, 'map[string]check.WhiteListEntry', self.allowentry),
            'deny': lambda n: self.mapping(n, 'map[string][]check.BlackListEntry', self.denyentry),
            'aliases': lambda n: self.mapping(n, 'map[string][]string', self.strings),
        })

    def validate(self, node):
        cfg = self.object(node, 'config.Config', {
            'exclude':self.strings, 'only':self.strings, 'unwrapExports':self.boolean,
            'check':self.check,
            'js':lambda n:self.object(n, 'js.Config', {'workspaces':self.boolean,'tsConfigPaths':self.boolean}),
            'python':lambda n:self.object(n, 'python.Config', {'excludeConditionalImports':self.boolean}),
            'rust':lambda n:self.object(n, 'rust.Config', {}),
        })
        if self.errors:
            raise YamlError('yaml: unmarshal errors:\n' + '\n'.join(self.errors))
        return cfg

def load_config(path=None, required=False):
    filename = path if path is not None else '.dep-tree.yml'
    base = os.path.dirname(absolute(filename))
    if path is None and not os.path.exists(filename):
        if required:
            raise Failure('when using the `check` subcommand, a .dep-tree.yml file must be provided, you can create one sample .dep-tree.yml file executing `dep-tree config` in your terminal')
        return {}, os.getcwd()
    try:
        with open(filename, encoding='utf-8') as f: text = f.read()
    except OSError as e:
        raise Failure(io_message(e, 'read' if os.path.isdir(filename) else 'open', filename))
    try:
        cfg = Validator().validate(YamlReader(text).parse())
    except YamlError as e:
        raise Failure('config file "%s" is not a valid yml file: %s' % (filename, e))
    return cfg, base
