DENY_TYPE = 'struct { To string "yaml:\\"to\\""; Reason string "yaml:\\"reason\\"" }'

class Validator:
    def __init__(self): self.errors = []

    def mismatch(self, node, target):
        value = node.value
        if isinstance(value, list): desc = '!!seq'
        elif isinstance(value, dict): desc = '!!map'
        elif isinstance(value, bool): desc = '!!bool `%s`' % str(value).lower()
        elif isinstance(value, int): desc = '!!int `%s`' % value
        elif isinstance(value, float): desc = '!!float `%s`' % value
