    def boolean(self, node):
        if node.value is None: return False
        if isinstance(node.value, bool): return node.value
        if isinstance(node.value, str):
            if node.value.lower() in ('yes', 'on', 'true'): return True
            if node.value.lower() in ('no', 'off', 'false'): return False
        self.mismatch(node, 'bool'); return False

    def strings(self, node):
        if node.value is None: return []
        if not isinstance(node.value, list):
            self.mismatch(node, '[]string'); return []
        return [self.string(v) for v in node.value]

    def object(self, node, typename, handlers):
        if node.value is None: return {}
        if not isinstance(node.value, dict):
            self.mismatch(node, typename); return {}
        result = {}
        for k, v in node.value.items():
            if k not in handlers:
                self.errors.append('  line %d: field %s not found in type %s' % (v.line, k, typename))
