        if isinstance(node.value, list): return {'to': self.strings(node), 'reason': ''}
        obj = self.object(node, ALLOW_TYPE, {'to': self.strings, 'reason': self.string})
        return {'to': obj.get('to', []), 'reason': obj.get('reason', '')}

    def denyentry(self, node):
        if node.value is None: return []
        if not isinstance(node.value, list):
            self.mismatch(node, '[]check.BlackListEntry'); return []
        result = []
        for n in node.value:
            if not isinstance(n.value, (dict,list)):
                result.append({'to':self.string(n), 'reason':''})
            else:
                o = self.object(n, DENY_TYPE, {'to':self.string, 'reason':self.string})
                result.append({'to':o.get('to',''), 'reason':o.get('reason','')})
