            if module is None:
                module=names[0]
                for root in roots:
                    target=absolute(module.replace('.','/'),root)
                    if os.path.isfile(target+'.py'):
                        node.dependencies.append(target+'.py');break
                    if os.path.isdir(target):
                        init=os.path.join(target,'__init__.py')
                        if os.path.isfile(init):node.dependencies.append(init)
                        break
                continue
            if level:
                parent=directory
                for _ in range(level-1):parent=os.path.dirname(parent)
                if not module:
                    path=os.path.join(parent,names[0]+'.py')
                    if os.path.isfile(path):node.dependencies.append(path)
                    else:node.errors.append('cannot import file %s.py from directory %s'%(names[0],parent))
                    continue
                target=absolute(module.replace('.','/'),parent)
                candidates=[target]
            else:
                candidates=[absolute(module.replace('.','/'),root) for root in roots]
            found=False
            for target in candidates:
                if os.path.isfile(target+'.py'):
                    node.dependencies.append(target+'.py');found=True;break
                if os.path.isdir(target):
                    found=True
                    deps=[];errors=[]
                    for name in names:
                        path=os.path.join(target,name+'.py')
                        init=os.path.join(target,'__init__.py')
                        if name!='*' and os.path.isfile(path):deps.append(path)
                        elif os.path.isfile(init):deps.append(init)
                        elif name!='*':errors.append('cannot import file %s.py from directory %s'%(name,target))
                    if deps:node.dependencies.extend(deps)
                    elif errors:node.errors.append(errors[0])
                    break
            if not found and level:
                node.errors.append('could not resolve relative import from %s to %s'%(directory,candidates[0]))

    def js_imports(self,text):
        ts=tokens(text)
