            t=ts[i]
            if t.kind!='id':i+=1;continue
            word=t.value
            if word in ('require','import') and i+2<len(ts) and ts[i+1].value=='(':
                if ts[i+2].kind=='string' and (i+3<len(ts) and ts[i+3].value in (')',',')):
                    if word=='import' or i==0 or ts[i-1].value!='.':result.append((ts[i+2].value,False))
