                    if not isinstance(value,str):continue
                    target=value.replace('*',fill)
                    found=self.resolve_js_file(absolute(target,opts.get('pathbase',opts['base'])))
                    if found:return found,False
            found=self.resolve_js_file(absolute(spec,opts['base']))
            if found:return found,False
        for name,directory,data in self.workspace_packages(node.path):
            if spec==name:
