            if path:node.dependencies.append(path)
            elif relative and not export:
                node.errors.append("could not perform relative import for '%s' because the file or dir was not found"%spec)

    def go_directory(self,directory):
        if directory in self.go_dirs:return self.go_dirs[directory]
        try:names=sorted(os.listdir(directory))
        except OSError as e:raise Failure(io_message(e,'open',directory))
        infos={}
        for name in names:
            if name.endswith('.go') and os.path.isfile(os.path.join(directory,name)):
                path=os.path.join(directory,name)
                info=self.go.get(path)
                if info.get('error'):raise Failure(info['error'])
                infos[path]=info
        self.go_dirs[directory]=infos
        return infos

    def golang(self,node,text):
        own=self.go.get(node.path)
        if own.get('error'):raise Failure(own['error'])
        node.package=own.get('package','')
        same=self.go_directory(os.path.dirname(node.path))
        declarations={}
        for path,info in same.items():
            if info['package']!=node.package:continue
            for symbol in info['declarations']:declarations.setdefault(symbol,path)
        module=node.project.metadata.get('module','')
        imports={};dot=[]
        for item in own['imports']:
