            elif module and p.startswith(module+'/'):directory=absolute(p[len(module)+1:],node.project.root)
            elif p.startswith('.'):directory=absolute(p,os.path.dirname(node.path))
            else:continue
            if alias=='_':continue
            default=os.path.basename(p)
            try:
                files=self.go_directory(directory)
                if files:
                    package=next(iter(files.values()))['package']
