"""Local import discovery for Python, ECMAScript, Go, and Rust.

Parsers are deliberately non-executing: source files are read as text/syntax,
never imported or run. Package resolution stays within local projects.
"""
import ast
import atexit
import io
import json
import os
import re
import subprocess
import sys
import tempfile
import tokenize
import zipfile
from dataclasses import dataclass, field
from common import Failure, absolute, parents, read_text, unique, io_message
from patterns import glob_paths, BadPattern

JS_EXTENSIONS = ('.js', '.ts', '.tsx', '.jsx', '.mjs', '.cjs')
ALL_JS = JS_EXTENSIONS + ('.mts', '.cts')

def language_for(path):
    ext = os.path.splitext(path)[1]
    if ext == '.py': return 'python'
    if ext in ALL_JS: return 'js'
    if ext == '.rs': return 'rust'
    if ext == '.go': return 'go'
    return None

@dataclass
class Token:
    kind: str
    value: str
    pos: int

def tokens(text, rust=False):
    """Lex code while hiding comments and string contents from keyword scans."""
    out = []
    i, size = 0, len(text)
    while i < size:
        c = text[i]
        if c.isspace(): i += 1; continue
        if text.startswith('//', i):
            j = text.find('\n', i+2); i = size if j < 0 else j+1; continue
        if text.startswith('/*', i):
            end, depth = i+2, 1
            while end < size and depth:
                if rust and text.startswith('/*', end): depth += 1; end += 2
                elif text.startswith('*/', end): depth -= 1; end += 2
                else: end += 1
            i = end; continue
        if text.startswith('#!', i) and i == 0:
            j = text.find('\n', i); i = size if j < 0 else j+1; continue
        if c in ('"', "'", '`'):
            # A Rust lifetime is an identifier, rather than a quoted string.
            if rust and c == "'" and re.match(r"'[A-Za-z_]\w*(?!')", text[i:]):
                m = re.match(r"'[A-Za-z_]\w*", text[i:])
                if i+len(m.group()) >= size or text[i+len(m.group())] != "'":
                    out.append(Token('id',m.group(),i));i += len(m.group());continue
            start, quote = i, c
            i += 1
            chars = []
            while i < size:
                c = text[i]
                if c == '\\' and i+1 < size:
                    nxt = text[i+1]
                    chars.append({'n':'\n','r':'\r','t':'\t'}.get(nxt,nxt)); i += 2
                elif c == quote:
                    i += 1; break
                else:
                    chars.append(c); i += 1
            out.append(Token('template' if quote == '`' else 'string', ''.join(chars), start))
            continue
        if c.isalpha() or c in '_$' or ord(c) > 127:
            j = i+1
            while j < size and (text[j].isalnum() or text[j] in '_$' or ord(text[j])>127): j += 1
            out.append(Token('id',text[i:j],i)); i=j; continue
        if c.isdigit():
            j=i+1
            while j<size and (text[j].isalnum() or text[j] in '._'): j+=1
            out.append(Token('number',text[i:j],i));i=j;continue
        if text.startswith('::', i):
            out.append(Token('punct','::',i));i+=2;continue
        out.append(Token('punct',c,i)); i+=1
    return out


def json_file(path, comments=False):
    try:
        with open(path, encoding='utf-8-sig') as f: text = f.read()
        if comments:
            # Comments in a tsconfig are conventional. Preserve quoted URLs.
            chunks=[]; i=0; quote=False; escaped=False
            while i<len(text):
                c=text[i]
                if quote:
                    chunks.append(c)
                    if escaped: escaped=False
                    elif c=='\\': escaped=True
                    elif c=='"': quote=False
                    i+=1
                elif c=='"': quote=True;chunks.append(c);i+=1
                elif text.startswith('//',i):
                    j=text.find('\n',i+2);i=len(text) if j<0 else j
                elif text.startswith('/*',i):
                    j=text.find('*/',i+2);i=len(text) if j<0 else j+2
                else: chunks.append(c);i+=1
            text=''.join(chunks)
            text=re.sub(r',\s*([}\]])',r'\1',text)
        data=json.loads(text)
        return data if isinstance(data,dict) else {}
    except (OSError,ValueError,UnicodeError):
        return {}

@dataclass
class Project:
    language: str
    root: str = ''
    name: str = ''
    metadata: dict = field(default_factory=dict)

@dataclass
class Parsed:
    path: str
    project: Project
    dependencies: list = field(default_factory=list)
    errors: list = field(default_factory=list)
    package: str = ''

    @property
    def relative(self):
        if not self.project.root: return ''
        try: return os.path.relpath(self.path,self.project.root)
        except ValueError: return ''

class GoReader:
    def __init__(self):
        self.process=None
        self.tmp=None
        self.cache={}
        atexit.register(self.close)

    def start(self):
        if self.process is not None: return
        archive=os.path.abspath(sys.argv[0])
        if zipfile.is_zipfile(archive):
            with zipfile.ZipFile(archive) as z: data=z.read('data/go-syntax')
            self.tmp=tempfile.TemporaryDirectory(prefix='dep-tree-syntax-')
            path=os.path.join(self.tmp.name,'reader')
            with open(path,'wb') as f:f.write(data)
            os.chmod(path,0o700)
        else:
            path=os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'build','go-syntax')
        self.process=subprocess.Popen([path],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True)

    def get(self,path):
        if path not in self.cache:
            self.start()
            self.process.stdin.write(json.dumps(path)+'\n');self.process.stdin.flush()
            line=self.process.stdout.readline()
            if not line: raise Failure('could not parse Go source '+path)
            self.cache[path]=json.loads(line)
        return self.cache[path]

    def close(self):
        if self.process:
            try:
                self.process.stdin.close()
                self.process.wait(timeout=1)
            except Exception:
                self.process.terminate()
            self.process=None
        if self.tmp:
            self.tmp.cleanup();self.tmp=None

class Scanner:
    def __init__(self, config=None):
        self.config=config or {}
        self.projects={}
        self.project_cache={}
        self.parsed={}
        self.go=GoReader()
        self.go_dirs={}
        self.rust_trees={}
        self.tsconfigs={}

    def git_committed(self,directory):
        git=os.path.join(directory,'.git')
        if os.path.isfile(git):
            try:
                text=read_text(git).strip()
                if text.startswith('gitdir:'):git=absolute(text[7:].strip(),directory)
            except Failure:return False
        head=os.path.join(git,'HEAD')
        try:
            with open(head) as f:value=f.read().strip()
            if value.startswith('ref: '):
                ref=value[5:]
                if os.path.isfile(os.path.join(git,ref)):return True
                packed=os.path.join(git,'packed-refs')
                if os.path.isfile(packed):
                    with open(packed) as f:return any(line.rstrip().endswith(' '+ref) for line in f)
                return False
            return bool(re.fullmatch(r'[a-fA-F0-9]{40,64}',value))
        except OSError:return False

    def project(self,path,lang=None):
        lang=lang or language_for(path)
        key=(os.path.dirname(path),lang)
        if key in self.project_cache:return self.project_cache[key]
        result=Project(lang or '')
        if lang=='python':
            for directory in parents(path):
                if any(os.path.isfile(os.path.join(directory,m)) for m in ('pyproject.toml','setup.py','requirements.txt','poetry.lock')) or self.git_committed(directory):
                    result=Project(lang,directory,os.path.basename(directory));break
        elif lang=='js':
            for directory in parents(path):
                data=json_file(os.path.join(directory,'package.json'))
                if isinstance(data.get('name'),str) and data['name']:
                    result=Project(lang,directory,data['name'].lstrip('@'),data);break
        elif lang=='go':
            for directory in parents(path):
                mod=os.path.join(directory,'go.mod')
                if os.path.isfile(mod):
                    text=read_text(mod)
                    m=re.search(r'(?m)^\s*module\s+(?:"([^"]+)"|([^\s]+))',text)
                    name=(m.group(1) or m.group(2)) if m else ''
                    result=Project(lang,directory,name,{'module':name});break
            if not result.root:
                raise Failure('no go.mod file found in any parent directory of '+path)
        elif lang=='rust':
            for directory in parents(path):
                if os.path.isfile(os.path.join(directory,'Cargo.toml')):
                    text=read_text(os.path.join(directory,'Cargo.toml'))
                    m=re.search(r'(?m)^\s*name\s*=\s*[\"\']([^\"\']+)',text)
                    result=Project(lang,directory,m.group(1) if m else os.path.basename(directory),{'toml':text});break
            if not result.root:
                raise Failure('panic: runtime error: invalid memory address or nil pointer dereference',2)
        ident=(lang,result.root)
        if ident not in self.projects:self.projects[ident]=result
        result=self.projects[ident]
        self.project_cache[key]=result
        return result

    def parse(self,path):
        if path in self.parsed:return self.parsed[path]
        lang=language_for(path)
        project=self.project(path,lang)
        node=Parsed(path,project)
        self.parsed[path]=node
        text=read_text(path)
        if lang=='python':self.python(node,text)
        elif lang=='js':self.javascript(node,text)
        elif lang=='go':self.golang(node,text)
        elif lang=='rust':self.rust(node,text)
        node.dependencies=[p for p in unique(node.dependencies) if p!=path]
        return node

    def label(self,path, multi=False):
        n=self.parsed.get(path)
        if n is None:
            project=self.project(path)
            n=Parsed(path,project)
            if project.language=='go': n.package=self.go.get(path).get('package','')
        label=n.relative
        if n.project.language=='go': return n.package+'@'+label
        if multi and n.project.name:return n.project.name+'@'+label
