"""Graph loading, cycle detection, dependency rules, and serialisation."""
import os
import sys
import time
from common import Failure, unique, absolute
from patterns import matches, compile_pattern, BadPattern

class Progress:
    def __init__(self):
        self.start=time.monotonic()
        self.previous=''
        self.count=0
        self.total=0
        self.render('',0,False)

    def render(self,description,count,clear=True):
        elapsed=time.monotonic()-self.start
        rate=int(count/max(elapsed,0.00001))
        speed=('%d it/s'%rate) if count else '0 it/hr'
        if description:
            body='⠋ (%d/%d) %s (%s) [%ds] '%(count,self.total,description,speed,int(elapsed))
        else:
            body='⠋  (%s) [%ds] '%(speed,int(elapsed))
        if clear and self.previous:
            sys.stderr.write('\r'+' '*(len(self.previous)+1)+'\r')
        sys.stderr.write('\r'+body)
        sys.stderr.flush()
        self.previous=body

    def step(self,total):
        self.count+=1
        self.total=max(self.total,total)
        if self.count==1:self.render('',self.count,False)
        else:self.render('Loading Files...',self.count)
        self.render('Loading Files...',self.count)

    def finish(self,total=None):
        if total is not None:self.total=max(self.total,total)
        self.render('Finished loading',self.count)
        self.render('Finished loading',self.count)
        sys.stderr.write('\n');sys.stderr.flush()

class Graph:
    def __init__(self, scanner, selection, roots, ignore_only=False, progress=None):
        self.scanner=scanner
        self.selection=selection
        self.roots=list(roots)
        self.nodes={}
        self.edges={}
        self.ignored=set()
        self.progress=progress
        self.scheduled=set(roots)
        def visit(path):
            if path in self.nodes or path in self.ignored:return
            if not selection.accepts(path,ignore_only):
                self.ignored.add(path);return
            node=scanner.parse(path)
            self.nodes[path]=node
            deps=[p for p in node.dependencies if selection.accepts(p,ignore_only)]
            self.edges[path]=deps
            self.scheduled.update(deps)
            if self.progress:self.progress.step(len(self.scheduled))
            for dep in deps:visit(dep)
        for path in roots:visit(path)
        if progress:progress.finish(len(self.scheduled))
        self.cycles=[]
        self.acyclic={p:[] for p in self.nodes}
        state={}
        stack=[]
        def dfs(path):
            if state.get(path)==2:return
            state[path]=1;stack.append(path)
            for dep in self.edges.get(path,[]):
                if dep not in self.nodes:continue
                if state.get(dep)==1:
                    self.cycles.append(stack[stack.index(dep):]+[dep])
                else:
                    self.acyclic[path].append(dep)
                    if state.get(dep)!=2:dfs(dep)
            stack.pop();state[path]=2
        for root in roots:
            if root in self.nodes and root not in state:dfs(root)
        # Projects are distinguished only among files that were actually read.
        self.multiple=len({(n.project.language,n.project.root) for n in self.nodes.values()})>1

    def label(self,path):
        return self.scanner.label(path,self.multiple)

    def json_tree(self,root):
        if root in self.ignored:
            raise Failure('selected entrypoint %s is explicitly ignored'%root)
        memo={}
        def branch(path):
            if path in memo:return memo[path]
            children={}
            for child in self.acyclic.get(path,[]):
                children[self.nodes[child].relative]=branch(child)
            result=dict(sorted(children.items())) if children else None
            memo[path]=result
            return result
        errors={}
        for path,node in self.nodes.items():
            if node.errors:errors[node.relative]=node.errors
        return {
            'tree':{self.nodes[root].relative:branch(root)},
            'circularDependencies':[[self.nodes[p].relative for p in cycle] for cycle in self.cycles],
            'errors':dict(sorted(errors.items())),
        }

    def explain(self,left,right):
        right=set(right)
        result=[]
        for path in left:
            if path not in self.nodes:continue
            for dep in self.edges.get(path,[]):
                if dep in right:
                    result.append(self.label(path)+' -> '+self.label(dep))
        return sorted(set(result))

    def check(self,config,base):
        aliases=config.get('aliases',{})
        def expand(values):
            answer=[]
            for value in values:answer.extend(aliases.get(value,[value]))
            return answer
        allowed=[];denied=[]
        try:
            for pattern,entry in sorted(config.get('allow',{}).items()):
                src=absolute(pattern,base)
                dest=[absolute(p,base) for p in expand(entry['to'])]
                compile_pattern(src)
                for p in dest:compile_pattern(p)
                allowed.append((src,dest,entry.get('reason','')))
            for pattern,entries in sorted(config.get('deny',{}).items()):
                src=absolute(pattern,base)
                compile_pattern(src)
                dest=[]
                for entry in entries:
                    for p in expand([entry['to']]):
                        p=absolute(p,base);compile_pattern(p)
                        dest.append((p,entry.get('reason','')))
                denied.append((src,dest))
        except BadPattern:
            raise Failure('syntax error in pattern')
        violations=[]
        for path in sorted(self.nodes):
            for dep in sorted(self.edges.get(path,[])):
                bad=False;reason=''
                for src,dest,r in allowed:
                    if matches(src,path):
                        if not any(matches(p,dep) for p in dest):bad=True;reason=r
                        break
                if not bad:
                    for src,dest in denied:
                        if matches(src,path):
                            for p,r in dest:
                                if matches(p,dep):bad=True;reason=r;break
                            if bad:break
                if bad:violations.append((path,dep,reason))
        cycles=[] if config.get('allowCircularDependencies',False) else self.cycles
        if not violations and not cycles:return
        text='Check failed, the following dependencies are not allowed:\n'
        for path,dep,reason in violations:
            text+='- '+os.path.relpath(path,base)+' -> '+os.path.relpath(dep,base)+'\n'
            if reason:
                text+='  '+reason.replace('\n','\n  ')+'\n'
        if cycles:
            text+='\ndetected circular dependencies:\n'
            for cycle in cycles:text+='- '+' -> '.join(self.label(p) for p in cycle)+'\n'
        raise Failure(text)
