const nodes=data.nodes,links=data.links;
const byId=new Map(nodes.map((n,i)=>[n.id,i]));
let width=innerWidth,height=innerHeight;
function resize(){width=canvas.width=innerWidth;height=canvas.height=innerHeight;}resize();addEventListener('resize',resize);
nodes.forEach((n,i)=>{const a=2*Math.PI*i/Math.max(1,nodes.length);n.x=width/2+Math.cos(a)*width*.28;n.y=height/2+Math.sin(a)*height*.28;n.vx=n.vy=0;});
document.getElementById('stats').textContent=nodes.length+' files, '+links.length+' dependencies';
let hover=-1;
