function frame(){ctx.clearRect(0,0,width,height);nodes.forEach((n,i)=>{let fx=(width/2-n.x)*.0007,fy=(height/2-n.y)*.0007;nodes.forEach((m,j)=>{if(i===j)return;let x=n.x-m.x,y=n.y-m.y,s=x*x+y*y+100;fx+=x*80/s;fy+=y*80/s;});n.vx=(n.vx+fx)*.8;n.vy=(n.vy+fy)*.8;});links.forEach(l=>{let a=nodes[byId.get(l.source)],b=nodes[byId.get(l.target)];if(!a||!b)return;let x=b.x-a.x,y=b.y-a.y,s=Math.hypot(x,y)||1,f=(s-90)*.002;a.vx+=x/s*f;a.vy+=y/s*f;b.vx-=x/s*f;b.vy-=y/s*f;ctx.strokeStyle='#475569';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();});nodes.forEach((n,i)=>{n.x+=n.vx;n.y+=n.vy;ctx.fillStyle=i===hover?'#fbbf24':'#818cf8';ctx.beginPath();ctx.arc(n.x,n.y,6,0,2*Math.PI);ctx.fill();});requestAnimationFrame(frame);}frame();
