    try:
        with open(path,'w',encoding='utf-8') as f:f.write(document)
    except OSError as e:raise Failure(io_message(e,'open',path))
    print(path)
    # Opening a browser is best-effort, just as viewing the same file manually.
    if not options.get('no-browser-open') and os.environ.get('DISPLAY'):
        import webbrowser
        webbrowser.open('file://'+absolute(path))


def run(argv):
    command,options,pos=arguments(argv)
    if options.get('version'):
        print('dep-tree version v0.23.4');return 0
    if options.get('help'):
        sys.stdout.write(help_text(command or 'root'));return 0
    if command is None:
        sys.stdout.write(help_text('root'));return 0
    if command=='init':command='config'
    if command=='help':
        target=pos[0] if pos and pos[0] in COMMANDS else 'root'
        sys.stdout.write(help_text(target));return 0
    if command in ('tree','entropy') and not pos:
        raise Failure('requires at least 1 arg(s), only received 0')
    if command=='explain' and len(pos)!=2:
        raise Failure('accepts 2 arg(s), received %d'%len(pos))
    if command in ('check','config') and pos:
        raise Failure('accepts 0 arg(s), received %d'%len(pos))
    if command=='config':
        if os.path.exists('.dep-tree.yml'):
            raise Failure('cannot generate config file, as one already exists in .dep-tree.yml')
        try:
            with open('.dep-tree.yml','w',encoding='utf-8') as f:f.write(resource('sample.yml'))
        except OSError as e:raise Failure(io_message(e,'open','.dep-tree.yml'))
        return 0
    if command=='explain' and options.get('overlap-left') and options.get('overlap-right'):
        raise Failure('only one of --overlap-left (-l) or --overlap-right (-r) can be used at a time')
    config,base=load_config(options.get('config'),command=='check')
    only=[absolute(p,base) for p in config.get('only',[])]+[absolute(p) for p in options.get('only',[])]
    exclude=[absolute(p,base) for p in config.get('exclude',[])]+[absolute(p) for p in options.get('exclude',[])]
    selection=Selection(only,exclude)
    right=[]
    if command=='check':
        checkcfg=config.get('check',{})
        entries=checkcfg.get('entrypoints',[])
        if not entries:raise Failure('config file "%s" has no entrypoints'%base)
        roots=[absolute(p,base) for p in entries]
        validate_language(roots)
    elif command=='explain':
        roots=expand_files([pos[0]])
        validate_language(roots)
        right=expand_files([pos[1]])
        if options.get('overlap-left'):right=[p for p in right if p not in set(roots)]
        elif options.get('overlap-right'):roots=[p for p in roots if p not in set(right)]
    else:
        roots=expand_files(pos)
        validate_language(roots)
    scanner=Scanner(config)
    progress=Progress()
    if command=='tree' and len(roots)!=1:
        raise Failure('this functionality requires that only 1 entrypoint is provided, but %d where passed. Consider providing a single entrypoint to your program'%len(roots))
    graph=Graph(scanner,selection,roots,ignore_only=command=='explain',progress=progress)
    if command=='tree':
        if options.get('json'):
            json_output(graph.json_tree(roots[0]))
        else:
            if roots[0] in graph.ignored:raise Failure('selected entrypoint %s is explicitly ignored'%roots[0])
            if not sys.stdin.isatty() or not sys.stdout.isatty():raise Failure('exit status 1')
            from terminal import show_tree
            show_tree(graph,roots[0])
    elif command=='explain':
        for line in graph.explain(roots,right):print(line)
    elif command=='check':graph.check(checkcfg,base)
    elif command=='entropy':render_entropy(graph,options)
    scanner.go.close()
    return 0


def main():
    try:
        code=run(sys.argv[1:])
    except Failure as e:
        if e.code==2 and str(e).startswith('panic:'):
            sys.stderr.write(str(e)+'\n')
        else:
            sys.stderr.write('Error: '+str(e)+'\n')
        code=e.code
    except BrokenPipeError:
        code=0
    except KeyboardInterrupt:
        code=130
    sys.exit(code)

if __name__=='__main__':main()
