#!/usr/bin/env python3
"""The dep-tree command-line application."""
import html
import json
import os
import sys
import tempfile
import zipfile
from common import Failure, absolute, io_message
from configuration import load_config
from patterns import Selection, glob_paths, BadPattern
from languages import Scanner, language_for
from graph import Graph, Progress

COMMANDS={'tree','entropy','explain','check','config','init','help'}
GLOBAL_STRINGS={'config','only','exclude'}
GLOBAL_BOOLS={'unwrap-exports','js-tsconfig-paths','js-workspaces','python-exclude-conditional-imports'}
LOCAL_BOOLS={'tree':{'json'},'explain':{'overlap-left','overlap-right'},'entropy':{'no-browser-open','enable-gui'}}
LOCAL_STRINGS={'entropy':{'render-path'}}
SHORT={'c':'config','h':'help','v':'version','l':'overlap-left','r':'overlap-right'}


def resource(name):
    archive=os.path.abspath(sys.argv[0])
    if zipfile.is_zipfile(archive):
        with zipfile.ZipFile(archive) as z:return z.read('data/'+name).decode('utf-8')
    with open(os.path.join(os.path.dirname(__file__),'data',name),encoding='utf-8') as f:return f.read()


def help_text(command='root'):
    if command=='init':command='config'
    return resource(command+'_help.txt')


def parse_bool(value,flag):
    if value in ('true','TRUE','True','1','t','T'):return True
    if value in ('false','FALSE','False','0','f','F'):return False
    raise Failure('invalid argument %s for "%s" flag: strconv.ParseBool: parsing %s: invalid syntax'%(json.dumps(value),flag,json.dumps(value)))


def arguments(argv):
    # Global switches may precede an explicit command. A positional first
    # argument that isn't a command selects the documented entropy default.
    command=None
    command_index=None
    skip=False
    root_help=False
    for i,arg in enumerate(argv):
        if skip:skip=False;continue
        if arg=='--':break
        if arg in ('-h','--help'):
            root_help=True;break
        if arg in ('-v','--version'):break
        if arg in ('-c','--config','--only','--exclude'):
            skip=True;continue
        if arg.startswith('-'):
            # Unknown/local flags before a command belong to the root command.
            name=arg[2:].split('=')[0] if arg.startswith('--') else SHORT.get(arg[1:2],'')
            if name not in GLOBAL_STRINGS|GLOBAL_BOOLS:break
            continue
        if arg in COMMANDS:
            command=arg;command_index=i
        else:
            command='entropy'
        break
    if root_help:command=None;command_index=None
    opt={'only':[],'exclude':[]}
    positions=[]
    i=0;end=False
    while i<len(argv):
        arg=argv[i]
        if command_index==i:i+=1;continue
        if arg=='--' and not end:end=True;i+=1;continue
        if not end and arg.startswith('--') and len(arg)>2:
            name,eq,value=arg[2:].partition('=')
            active=command if (command_index is None or i>command_index) else None
            bools=GLOBAL_BOOLS|{'help'}|LOCAL_BOOLS.get(active,set())
            if active is None:bools=bools|{'version'}
            strings=GLOBAL_STRINGS|LOCAL_STRINGS.get(active,set())
            if name in bools:
                opt[name]=parse_bool(value,'--'+name) if eq else True
            elif name in strings:
                if not eq:
                    i+=1
                    if i>=len(argv):raise Failure('flag needs an argument: --'+name)
                    value=argv[i]
                if name in ('only','exclude'):opt[name].append(value)
                else:opt[name]=value
            else:raise Failure('unknown flag: --'+name)
        elif not end and arg.startswith('-') and len(arg)>1:
            short=arg[1:];j=0
            active=command if (command_index is None or i>command_index) else None
            while j<len(short):
                ch=short[j];name=SHORT.get(ch)
                permitted=GLOBAL_BOOLS|GLOBAL_STRINGS|{'help'}|LOCAL_BOOLS.get(active,set())
                if active is None:permitted.add('version')
                if name is None or name not in permitted:
                    raise Failure("unknown shorthand flag: '%s' in %s"%(ch,arg))
                if name=='config':
                    if j+1<len(short):value=short[j+1:];value=value[1:] if value.startswith('=') else value
                    else:
                        i+=1
                        if i>=len(argv):raise Failure('flag needs an argument: -c')
                        value=argv[i]
                    opt[name]=value;break
                if j+1<len(short) and short[j+1]=='=':
                    opt[name]=parse_bool(short[j+2:],'-'+ch);break
                opt[name]=True;j+=1
        else:positions.append(arg)
        i+=1
    return command,opt,positions


def expand_files(patterns):
    paths=[]
    for pattern in patterns:
        try:found=glob_paths(pattern)
        except BadPattern:raise Failure('syntax error in pattern')
        if not found:raise Failure(pattern+' does not match with any existing file')
        paths.extend(p for p in found if not os.path.isdir(p))
    if not paths:raise Failure('no valid files where provided')
    return paths


def validate_language(paths):
    if not any(language_for(p) for p in paths):
        raise Failure('none of the provided files belong to the a supported language')


def json_output(obj):
    # Match JSON's HTML-safe escaping while preserving UTF-8 filenames.
    text=json.dumps(obj,indent=2,ensure_ascii=False)
    text=text.replace('&',r'\u0026').replace('<',r'\u003c').replace('>',r'\u003e')
    text=text.replace('\u2028',r'\u2028').replace('\u2029',r'\u2029')
    sys.stdout.write(text+'\n')


