    if path is None or path=='':
        fd,path=tempfile.mkstemp(prefix='dep-tree-',suffix='.html');os.close(fd)
    nodes=[{'id':p,'name':graph.label(p),'path':n.relative} for p,n in graph.nodes.items()]
    links=[{'source':p,'target':d} for p,ds in graph.edges.items() for d in ds if d in graph.nodes]
    data=json.dumps({'nodes':nodes,'links':links},ensure_ascii=False).replace('</','<\\/')
    # Self-contained, original graph viewer. The generated page requires no
    # network connection or third-party JavaScript libraries.
    document='''<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Dep Tree</title>
