"""Keyboard-driven dependency tree display."""
import curses

HELP=[
    'j      -> move one step down',
    'k      -> move one step up',
    'Ctrl d -> move half page down',
    'Ctrl u -> move half page up',
    'Enter  -> select the current node as the root node',
    'q      -> navigate backwards on selected nodes or quit',
    'h      -> show this help section',
]

def show_tree(graph,root):
    def interface(screen):
        curses.curs_set(0)
        screen.keypad(True)
        stack=[]
        current=root
        selected=0
        showing_help=False
        while True:
            screen.erase()
            height,width=screen.getmaxyx()
            rows=[]
            def visit(path,prefix='',last=True,top=False):
                rows.append((path,prefix+('' if top else '└── ' if last else '├── ')+graph.label(path)))
                children=graph.acyclic.get(path,[])
                for i,child in enumerate(children):
                    visit(child,prefix+('' if top else '    ' if last else '│   '),i==len(children)-1)
            visit(current,top=True)
            selected=min(selected,max(0,len(rows)-1))
            if showing_help:
                for y,text in enumerate(HELP):
                    if y<height-1:screen.addnstr(y,0,text,max(0,width-1))
            else:
                offset=max(0,selected-height+2)
                for y,(path,text) in enumerate(rows[offset:offset+height-1]):
                    screen.addnstr(y,0,text,max(0,width-1),curses.A_REVERSE if offset+y==selected else 0)
            screen.refresh()
            key=screen.getch()
            if key in (ord('h'),ord('?')):showing_help=not showing_help;continue
            if showing_help:showing_help=False;continue
            if key in (ord('q'),27):
                if not stack:break
                current,selected=stack.pop()
            elif key in (ord('j'),curses.KEY_DOWN):selected=min(len(rows)-1,selected+1)
            elif key in (ord('k'),curses.KEY_UP):selected=max(0,selected-1)
            elif key in (4,curses.KEY_NPAGE):selected=min(len(rows)-1,selected+max(1,height//2))
            elif key in (21,curses.KEY_PPAGE):selected=max(0,selected-max(1,height//2))
            elif key in (10,13,curses.KEY_ENTER):
                target=rows[selected][0]
                if target!=current:stack.append((current,selected));current=target;selected=0
    curses.wrapper(interface)
