"""Interactive, line-oriented drawing of a dependency DAG.

Active dependency columns persist between topological layers, allowing shared
children to be drawn once. Backwards edges are routed to the right of labels.
"""
import os
import select
import sys
import termios
import tty
from collections import defaultdict

HELP = r'''
 ____         _ __       _
|  _ \   ___ |  _ \    _| |_  _ __  ___   ___
| | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
| |_| ||  __/| .__/     | |  | |  |  __/|  __/
|____/  \__| |_|        | \__|_|   \___| \___|

Welcome to dep-tree's help section.

j      -> move one step down
k      -> move one step up
Ctrl d -> move half page down
Ctrl u -> move half page up
Enter  -> select the current node as the root node
q      -> navigate backwards on selected nodes or quit
h      -> show this help section
'''

UP, DOWN, LEFT, RIGHT = 1, 2, 4, 8
GLYPHS={UP:'│',DOWN:'│',UP|DOWN:'│',LEFT:'─',RIGHT:'─',LEFT|RIGHT:'─',
        DOWN|RIGHT:'┌',UP|RIGHT:'└',DOWN|LEFT:'┐',UP|LEFT:'┘',
        UP|DOWN|RIGHT:'├',UP|DOWN|LEFT:'┤',LEFT|RIGHT|DOWN:'┬',LEFT|RIGHT|UP:'┴',
        UP|DOWN|LEFT|RIGHT:'┼'}

class Layout:
    def __init__(self, graph, root):
        self.graph=graph
        self.root=root
        self.forward={}
        self.backward=[]
        state={}
        def visit(p):
            state[p]=1;self.forward[p]=[]
            for q in graph.edges.get(p,[]):
                if q not in graph.nodes:continue
                if state.get(q)==1:self.backward.append((p,q))
                else:
                    self.forward[p].append(q)
                    if not state.get(q):visit(q)
            state[p]=2
        visit(root)
        indegree={p:0 for p in self.forward}
        for ds in self.forward.values():
            for p in ds:indegree[p]+=1
        ready=[root];layers=[]
        while ready:
            layers.append(sorted(ready,key=lambda p:graph.nodes[p].relative))
            nextlayer=[]
            for p in ready:
                for q in self.forward[p]:
                    indegree[q]-=1
                    if indegree[q]==0:nextlayer.append(q)
            ready=nextlayer
        self.positions={}
        self.row_nodes={}
        self.routes=defaultdict(list)
        self.bits=[]
        self.special=[]
        self.labels={}
        active={}
        max_previous=0
        for level,layer in enumerate(layers):
            arrow=max_previous+1
            if level:
                self.bits.append({column:UP|DOWN for column,ds in active.values()})
                self.special.append({})
            layer_max=0
            for p in layer:
                row=len(self.bits)
                bits={column:UP|DOWN for column,ds in active.values()}
                special={}
                incoming=[parent for parent,(column,ds) in active.items() if p in ds]
                if level:
                    for parent in sorted(incoming,key=lambda q:active[q][0]):
                        column,ds=active[parent]
                        ds.remove(p)
                        bits[column]=UP|RIGHT|(DOWN if ds else 0)
                        for x in range(column+1,arrow):bits[x]=bits.get(x,0)|LEFT|RIGHT
                        special[arrow]='▷'
                        self.routes[parent].append((row,column,arrow,bool(ds)))
                    for parent in incoming:
                        if not active[parent][1]:del active[parent]
                    column=max([arrow+1]+[c+1 for c,ds in active.values()])
                else:
                    column=0;bits={}
                label=graph.nodes[p].relative
                self.positions[p]=(row,column)
                self.row_nodes[row]=p
                self.labels[row]=(column,label)
                layer_max=max(layer_max,column)
                self.bits.append(bits);self.special.append(special)
                if self.forward[p]:active[p]=(column,set(self.forward[p]))
            max_previous=layer_max
        self.back_routes={}
        # Share the return lane for backwards edges originating at one node.
        targets={q for p,q in self.backward}
        for source in dict.fromkeys(p for p,q in self.backward):
            ends=[q for p,q in self.backward if p==source]
            sy,sx=self.positions[source]
            top=min(self.positions[q][0] for q in ends)
            bus=max(col+len(label) for row,(col,label) in self.labels.items() if top<=row<=sy)
            if source in targets:bus+=1
            for target in ends:
                ty,tx=self.positions[target]
                endpoint=tx+len(graph.nodes[target].relative)
                start=sx+len(graph.nodes[source].relative)+(1 if source in targets else 0)
                self.special[ty][endpoint]='◁'
                for x in range(endpoint+1,bus):self.bits[ty][x]=self.bits[ty].get(x,0)|LEFT|RIGHT
                self.bits[ty][bus]=self.bits[ty].get(bus,0)|LEFT|DOWN
                for y in range(ty+1,sy):self.bits[y][bus]=self.bits[y].get(bus,0)|UP|DOWN
                for x in range(start,bus):self.bits[sy][x]=self.bits[sy].get(x,0)|LEFT|RIGHT
                self.bits[sy][bus]=self.bits[sy].get(bus,0)|LEFT|UP
                self.back_routes[(source,target)]=(sy,start,ty,endpoint,bus)

    def picture(self, selected):
        lines=[];colors=[]
        for y,bits in enumerate(self.bits):
            chars={x:GLYPHS.get(value,'─') for x,value in bits.items()}
            chars.update(self.special[y])
            if y in self.labels:
                column,label=self.labels[y]
                for i,c in enumerate(label):chars[column+i]=c
            width=max(chars,default=-1)+1
            line=[' ']*width
            for x,c in chars.items():line[x]=c
            lines.append(line);colors.append({})
        focus=self.row_nodes.get(selected)
        if focus is None:return lines,colors,None
        def put(y,x,c,color=32):
            if y>=len(lines) or x<0:return
            if len(lines[y])<=x:lines[y].extend([' ']*(x+1-len(lines[y])))
            lines[y][x]=c;colors[y][x]=color
        fy,fx=self.positions[focus]
        if self.routes.get(focus):
            last=max(r[0] for r in self.routes[focus])
            for y in range(fy+1,last+1):put(y,fx,'│')
            for y,x,arrow,more in self.routes[focus]:
                put(y,x,'├' if more else '└')
                for xx in range(x+1,arrow):put(y,xx,'─')
                put(y,arrow,'▷')
        for (source,target),(sy,start,ty,endpoint,bus) in self.back_routes.items():
            if source!=focus:continue
            put(ty,endpoint,'◁')
            for x in range(endpoint+1,bus):put(ty,x,'─')
            put(ty,bus,'┐')
            for y in range(ty+1,sy):put(y,bus,'│')
            for x in range(start,bus):put(sy,x,'─')
            put(sy,bus,'┘')
        targets=set(self.graph.edges.get(focus,[]))
        for p,(y,column) in self.positions.items():
            color=35 if self.graph.nodes[p].errors else 32 if p==focus else 36 if p in targets else 39
            for x in range(column,column+len(self.graph.nodes[p].relative)):colors[y][x]=color
        return lines,colors,focus


def wrap_error(error,width):
    words=('- '+error).split(' ')
    result=[];line=''
    for word in words:
        if len(line)+len(word)+1>width and line:
            result.append(line);line=''
        line+=word+' '
    if line:result.append(line)
    return result


def show_tree(graph,root):
    fd=sys.stdin.fileno()
    original=termios.tcgetattr(fd)
    current=root;selected=0;offset=0;history=[];help_screen=False
    layout=Layout(graph,current)
    def size():
        try:s=os.get_terminal_size(sys.stdout.fileno());return s.lines,s.columns
        except OSError:return 24,80
    def draw():
        nonlocal offset
        height,width=size()
        if help_screen:
            sys.stdout.write('\033[H\033[2J'+HELP.replace('\n','\r\n'))
            sys.stdout.flush();return
        lines,colors,focus=layout.picture(selected)
        if selected<offset:offset=selected
        if selected>=offset+height:offset=selected-height+1
        error_lines=[]
        if focus is not None:
            for e in graph.nodes[focus].errors:error_lines.extend(wrap_error(e,40))
        edge=max(0,width-40)
        output=['\033[H\033[2J']
        for screenrow in range(height):
            y=screenrow+offset
            row=lines[y][:] if y<len(lines) else []
            c=dict(colors[y]) if y<len(colors) else {}
            if screenrow<len(error_lines):
                if len(row)<edge:row+=[' ']*(edge-len(row))
                row=row[:edge]+list(error_lines[screenrow])
                for x in range(edge,len(row)):c[x]=31
            last=39
            for x,ch in enumerate(row[:width]):
                color=c.get(x,39)
                if color!=last:output.append('\033[%dm'%color);last=color
                output.append(ch)
            if last!=39:output.append('\033[39m')
            if screenrow+1<height:output.append('\r\n')
        sys.stdout.write(''.join(output));sys.stdout.flush()
    try:
        tty.setraw(fd)
        sys.stdout.write('\033[?25l')
        draw()
        while True:
            key=os.read(fd,1)
            if not key:break
            if key==b'\x03':break
            if key==b'\x1b' and select.select([fd],[],[],.02)[0]:
                key+=os.read(fd,1)
                if select.select([fd],[],[],.02)[0]:key+=os.read(fd,1)
            if help_screen:
                if key in (b'q',b'\x1b'):help_screen=False;draw()
                continue
            if key==b'h':help_screen=True
            elif key in (b'q',b'\x1b'):
                if not history:break
                current,selected,offset=history.pop();layout=Layout(graph,current)
            elif key in (b'j',b'\x1b[B'):selected=min(len(layout.bits)-1,selected+1)
            elif key in (b'k',b'\x1b[A'):selected=max(0,selected-1)
            elif key==b'\x04':selected=min(len(layout.bits)-1,selected+max(1,size()[0]//2))
            elif key==b'\x15':selected=max(0,selected-max(1,size()[0]//2))
            elif key in (b'\r',b'\n'):
                target=layout.row_nodes.get(selected)
                if target is not None and target!=current:
                    history.append((current,selected,offset));current=target;selected=0;offset=0;layout=Layout(graph,current)
            draw()
    finally:
        termios.tcsetattr(fd,termios.TCSADRAIN,original)
        sys.stdout.write('\033[0m\033[?25h')
        sys.stdout.flush()
EOF
